import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Variantes de hechizos y glifos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/variants-and-glyphs.md","filePath":"es/guide/magic/variants-and-glyphs.md"}'),o={name:"es/guide/magic/variants-and-glyphs.md"};function n(r,e,d,l,c,m){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="spell-variants-and-glyphs" tabindex="-1">Variantes de hechizos y glifos <a class="header-anchor" href="#spell-variants-and-glyphs" aria-label="Enlace permanente a &quot;Variantes de hechizos y glifos&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> <strong>Implementación:</strong> no se ha establecido que este rediseño esté implementado. <strong>Disponibilidad:</strong> no se ha establecido que esté disponible en juego. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Los glifos aprendidos pueden modificar Core Patterns compatibles con contrapartidas significativas.</li><li>Un presupuesto acotado de complejidad impide acumularlos sin límite; las combinaciones exactas siguen abiertas.</li><li>Preparar un hechizo base no resuelve automáticamente los requisitos de memoria de todas sus variantes.</li></ul><p><a href="/Syrolands-Public/es/game-design/magic/variants-and-glyphs.html">Especificación completa del diseño</a></p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Función / límite Propuesto</th></tr></thead><tbody><tr><td>Qué cambian los glifos</td><td>Los glifos aprendidos pueden cambiar la forma, entrega, selección de objetivo, efecto o coste/estabilidad de un patrón conocido. Un proyectil más concentrado, una explosión más amplia, un campo persistente o un lanzamiento más difícil dirigido a una extremidad son ejemplos, no opciones de hechizo garantizadas.</td></tr><tr><td>Límites y contrapartidas</td><td>Todo modificador necesita una contrapartida. La compatibilidad depende del patrón y un presupuesto acotado de complejidad impide la acumulación ilimitada. El número exacto de modificadores y sus combinaciones siguen sin decidirse.</td></tr><tr><td>Memoria e Inscription</td><td>Una variante modificada puede necesitar su propia complejidad de memoria o un esfuerzo adicional de reconstrucción; memorizar Fireball no determina cómo funciona cada variante de Fireball. Inscription podría conservar variantes útiles en pergaminos o libros físicos.</td></tr><tr><td>Efectos legibles</td><td>Los efectos visuales deberían explicar la diferencia: Compression podría verse más concentrada y Persistence podría dejar un campo visible. La <a href="/Syrolands-Public/es/game-design/magic/presentation.html">presentación modular</a> es una meta de diseño, no un renderizador implementado. <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria</a> · <a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a>.</td></tr></tbody></table>',7)])])}const h=a(o,[["render",n]]);export{u as __pageData,h as default};
